// 打卡管理：统一删除 + 批量调整积分 + 分类筛选 + 积分排序
function renderCheckInManage() {
    const prefs = getManagePrefs();
    const filterCategory = prefs.manageFilterCategory || '';
    const sortMode = prefs.manageSortPoints || 'pointsAsc';
    const cats = getCategories();
    const order = getCategoryOrder();
    // 筛选选项基于 categories（改名后即时同步），不仅限于已有习惯的 category
    const allCategories = order.map(k => cats[k]).filter(Boolean);
    let items = state.data.checkIns.slice();
    if (filterCategory) {
        items = items.filter(it => it.category === filterCategory);
    }
    items.sort((a, b) => {
        if (sortMode === 'pointsAsc') return (a.points || 0) - (b.points || 0) || a.order - b.order;
        if (sortMode === 'pointsDesc') return (b.points || 0) - (a.points || 0) || a.order - b.order;
        return a.order - b.order;
    });
    const categoryOptions = [['', '全部分类'], ...allCategories.map(c => [c, c])];
    return renderCheckInAddForm() + `
        <div class="card">
            <div class="card-header">
                <div class="card-title">🛠️ 打卡项批量管理</div>
                <span style="font-size:13px;color:var(--text-secondary)">${items.length} 项 · 勾选后可批量操作</span>
            </div>
            <div class="manage-filter-bar">
                <select class="input manage-filter-select" data-action="manage-filter-category">
                    ${categoryOptions.map(([val, label]) => `<option value="${escapeHtml(val)}" ${val === filterCategory ? 'selected' : ''}>${escapeHtml(label)}</option>`).join('')}
                </select>
                <select class="input manage-filter-select" data-action="manage-sort-points">
                    <option value="pointsAsc" ${sortMode === 'pointsAsc' ? 'selected' : ''}>积分由小到大</option>
                    <option value="pointsDesc" ${sortMode === 'pointsDesc' ? 'selected' : ''}>积分由大到小</option>
                    <option value="order" ${sortMode === 'order' ? 'selected' : ''}>按添加顺序</option>
                </select>
            </div>
            <div class="manage-bar">
                <label class="manage-select-all">
                    <input type="checkbox" id="manageSelectAll" data-action="manage-select-all"> 全选
                </label>
                <select class="input" id="manageTargetCategory" title="批量移动到目标板块" style="flex:1;min-width:100px">
                    <option value="">移动到…</option>
                    ${order.map(k => `<option value="${escapeHtml(k)}">${escapeHtml(cats[k] || k)}</option>`).join('')}
                </select>
                <button class="btn btn-secondary" data-action="manage-batch-category">移动</button>
                <select class="input" id="manageTargetStars" title="批量统一花朵数" style="flex:1;min-width:100px">
                    <option value="">统一花朵…</option>
                    ${[1,2,3,4,5].map(n => `<option value="${n}">${n} 朵 · ${flowerScore(n)} 分</option>`).join('')}
                </select>
                <button class="btn btn-secondary" data-action="manage-batch-stars">设花</button>
                <button class="btn btn-danger" data-action="manage-batch-delete">删除</button>
            </div>
            <div class="manage-bar" style="margin-top:0;margin-bottom:18px;">
                <input type="number" class="input" id="managePoints" placeholder="统一积分" style="flex:1;min-width:70px">
                <button class="btn btn-primary" data-action="manage-batch-points">设分</button>
            </div>
            <div class="manage-list">
                ${items.length ? items.map(it => `
                    <div class="manage-row" data-id="${it.id}">
                        <input type="checkbox" class="manage-check" value="${it.id}">
                        <div class="manage-body">
                            <div class="manage-name-line">
                                <span class="manage-name">${escapeHtml(it.name)}</span>
                                <button type="button" class="task-edit" data-action="edit-checkin" data-id="${it.id}" title="编辑名称/分组/分数">✎</button>
                            </div>
                            <div class="manage-tags">
                                <span class="cat-tag">${it.category}</span>
                                <span class="diff-tag">${flowerLevel(it.stars||3).slogan}</span>
                                <span class="pts-tag">${it.points}分</span>
                            </div>
                        </div>
                    </div>
                `).join('') : '<div class="empty-state"><span class="emoji">📝</span>还没有打卡项</div>'}
            </div>
        </div>
    `;
}

// ==================== 阅读板块（重建：每日推荐 + 收藏书屋） ====================

// 每日推荐：按当天日期从 BOOKS 中轮询取 2 本（每天不同，跨天自动变化）
function getDailyReadingBooks() {
    const n = BOOKS.length;
    if (n === 0) return [];
    const d = new Date();
    // 用「年*366+月*31+日」做种子，保证同一天稳定、跨天变化，且均匀铺开
    const seed = d.getFullYear() * 366 + (d.getMonth() + 1) * 31 + d.getDate();
    const start = seed % n;
    const count = Math.min(2, n);
    const out = [];
    for (let i = 0; i < count; i++) {
        out.push(BOOKS[(start + i) % n]);
    }
    return out;
}

// 是否已看过（收藏）
function isBookRead(title) {
    return Array.isArray(state.data.bookRead) && state.data.bookRead.some(b => b.title === title);
}

// 标记看过 / 取消看过（看过即进入收藏书屋）
// 标记看过（幂等：已收藏则不变），看过即进入收藏书屋
function markBookRead(book) {
    if (!Array.isArray(state.data.bookRead)) state.data.bookRead = [];
    if (state.data.bookRead.some(b => b.title === book.title)) { render(); return; }
    state.data.bookRead.unshift({
        title: book.title,
        author: book.author || '',
        tags: Array.isArray(book.tags) ? book.tags : [],
        desc: book.desc || '',
        rating: typeof book.rating === 'number' ? book.rating : null,
        markedAt: now()
    });
    saveState(); render();
    toast('已标记为看过，收藏到书屋 🏠');
}

// 取消看过 / 移出书屋（幂等：未收藏则不变）
function unmarkBookRead(book) {
    if (!Array.isArray(state.data.bookRead)) state.data.bookRead = [];
    const idx = state.data.bookRead.findIndex(b => b.title === book.title);
    if (idx < 0) { render(); return; }
    state.data.bookRead.splice(idx, 1);
    saveState(); render();
    toast('已移出收藏书屋');
}

// 豆瓣搜索跳转：打开对应书籍的搜索结果页
function openDoubanBookSearch(keyword) {
    const q = encodeURIComponent(keyword || '');
    if (!q) { toast('请输入想搜的书名或作者'); return; }
    const url = 'https://search.douban.com/book/subject_search?search_text=' + q;
    window.open(url, '_blank', 'noopener');
}

// 每日阅读视图
function renderReading() {
    const books = getDailyReadingBooks();
    const todayStr = new Date().toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' });
    const cards = books.map((b, i) => {
        const read = isBookRead(b.title);
        const tags = (Array.isArray(b.tags) ? b.tags : []).map(t => `<span class="book-tag">${escapeHtml(t)}</span>`).join('');
        const rating = typeof b.rating === 'number'
            ? `<span class="book-rating">★ ${b.rating.toFixed(1)}</span>` : '';
        return `
        <div class="book-card reading-daily-card">
            <div class="book-num">${i + 1}</div>
            <div class="book-info">
                <div class="book-title">${escapeHtml(b.title)}</div>
                <div class="book-author">${escapeHtml(b.author || '佚名')}</div>
                <div class="book-tags">${tags} ${rating}</div>
                <div class="book-desc">${escapeHtml(b.desc || '')}</div>
                <div class="book-actions">
                    <button class="btn ${read ? 'btn-outline' : 'btn-primary'} reading-mark-btn"
                            data-action="${read ? 'reading-unfavorite' : 'reading-mark'}" data-title="${escapeHtml(b.title)}">
                        ${read ? '✓ 已看过 · 取消' : '👁 看过'}
                    </button>
                    <button class="btn btn-ghost reading-search-btn"
                            data-action="reading-search" data-keyword="${escapeHtml(b.title + ' ' + (b.author || ''))}">
                        🔍 在豆瓣看
                    </button>
                </div>
            </div>
        </div>`;
    }).join('');

    return `
        <div class="reading-wrap">
            <div class="reading-search-row">
                <span class="reading-search-label">🔍 搜你想看的书，直接跳转豆瓣：</span>
                <div class="reading-search-input-wrap">
                    <input type="text" id="readingSearchInput" class="input reading-search-input"
                           placeholder="输入书名或作者，回车或点击搜索…" data-action="reading-search-input">
                    <button class="btn btn-primary reading-search-go" data-action="reading-search-go">搜索</button>
                </div>
                <div class="reading-search-tip">点击「今日推荐」卡片上的「在豆瓣看」也能一键直达</div>
            </div>

            <div class="reading-daily-head">
                <h3>📅 每日推荐 · ${escapeHtml(todayStr)}</h3>
                <span class="reading-daily-sub">每天 2 本，今天刚好陪你读点不一样的</span>
            </div>

            <div class="reading-daily-list">
                ${cards || '<div class="empty">书库暂时为空</div>'}
            </div>
        </div>`;
}

// 收藏书屋视图
function renderBookShelf() {
    const read = Array.isArray(state.data.bookRead) ? state.data.bookRead : [];
    if (!read.length) {
        return `
        <div class="reading-wrap">
            <div class="reading-shelf-head">
                <h3>🏠 我的收藏书屋</h3>
                <span class="reading-daily-sub">在「每日阅读」点「看过」，书就会来到这里</span>
            </div>
            <div class="empty">
                <span class="emoji">📚</span>
                书屋还空着，去「每日阅读」标记一本看过的书吧～
            </div>
        </div>`;
    }
    const items = read.map((b, i) => {
        const tags = (Array.isArray(b.tags) ? b.tags : []).map(t => `<span class="book-tag">${escapeHtml(t)}</span>`).join('');
        const rating = typeof b.rating === 'number' ? `<span class="book-rating">★ ${b.rating.toFixed(1)}</span>` : '';
        return `
        <div class="book-card reading-shelf-card">
            <div class="book-num">${i + 1}</div>
            <div class="book-info">
                <div class="book-title">${escapeHtml(b.title)}</div>
                <div class="book-author">${escapeHtml(b.author || '佚名')}</div>
                <div class="book-tags">${tags} ${rating}</div>
                <div class="book-desc">${escapeHtml(b.desc || '')}</div>
                <div class="book-actions">
                    <button class="btn btn-ghost reading-search-btn"
                            data-action="reading-search" data-keyword="${escapeHtml(b.title + ' ' + (b.author || ''))}">
                        🔍 在豆瓣看
                    </button>
                    <button class="btn btn-outline reading-unfav-btn"
                            data-action="reading-unfavorite" data-title="${escapeHtml(b.title)}">
                        移出书屋
                    </button>
                </div>
            </div>
        </div>`;
    }).join('');

    return `
        <div class="reading-wrap">
            <div class="reading-shelf-head">
                <h3>🏠 我的收藏书屋</h3>
                <span class="reading-daily-sub">共收藏 ${read.length} 本</span>
            </div>
            <div class="reading-daily-list">
                ${items}
            </div>
        </div>`;
}



